TELEMETRY_POINT_COUNT = 961
HOUSEKEEPING_POINT_COUNT = 320
TELEMETRY_BY_ID = {t.id: t for t in TELEMETRY_POINTS}
TELEMETRY_BY_MNEMONIC = {t.mnemonic: t for t in TELEMETRY_POINTS}
RATE_SET_BY_MODE = {r.mode: r for r in MODE_RATE_SETS}


def sample_rate_hz(point: TelemetryPoint, mode: str) -> float | None:
    rate_set = RATE_SET_BY_MODE[mode]
    if point.kind == 'housekeeping' and rate_set.housekeeping_period_s:
        return 1.0 / rate_set.housekeeping_period_s
    return point.rate_hz
